pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an address that we will mark approved in the reference.
    // General rule: for any address a, after setApprovedLogger(a, true) called by owner,
    // c.approvedToLog(a) returns true. The mutant that always returns false will fail for such a
    // fuzzed approved address. We fuzz the address so the fuzzer can find any admissible address.
    function testFuzz_property(address logger) public {
        // make sure logger is not zero to keep domain wide but reasonable
        vm.assume(logger != address(0));

        // set msg.sender as owner (deployed contract creator is this test contract)
        // The c was deployed by this contract in setUp(), so this contract is the owner.

        // Approve the fuzzed logger
        c.setApprovedLogger(logger, true);

        // Now read the public view; this must be true on the reference for every logger we approved.
        bool ok;
        try c.approvedToLog(logger) returns (bool v) {
            ok = v;
        } catch {
            ok = false;
        }

        // Exactly one assertion: reference returns true for approved logger; mutant (always false)
        // will cause this assertion to fail for at least some inputs (any approved logger).
        assertTrue(ok);
    }
}

