contract InvMutTest is Test {
    C c;
    address ownerCandidate;

    function setUp() public { c = new C(); }

    // Fuzz: pick an address that we'll set as approved logger and also try to treat as owner candidate
    function testFuzz_property(address logger) public {
        // keep wide domain but avoid zero address since owner may be zero in some deployments
        if (logger == address(0)) return;

        // We need to setApprovedLogger which is onlyOwner. The contract's owner (_contractOwner) is private and
        // set at construction; we don't know it. To allow the test to set mapping for arbitrary address `logger`,
        // we must call setApprovedLogger as the owner. We cannot assume the test's address is owner, so we
        // attempt to call setApprovedLogger via address(c) owner by performing a low-level call impersonation.
        // However forge's vm.prank can impersonate any address only for the EVM; we need the contract owner address.
        // We can instead rely on the fact that the contract's constructor sets the deployer (this test) as owner
        // because we used `new C()` in setUp from this test contract. Thus this contract is the owner and can set loggers.

        // Set `logger` as approved in the mapping via the owner (this test contract is the deployer/owner)
        c.setApprovedLogger(logger, true);

        // Now check the general property: in the reference, approvedToLog(logger) == approvedLoggers[logger] == true.
        // We assert that approvedToLog(logger) is true. This holds for the reference C for all logger addresses that
        // we set to true. The mutant will return false when logger == contract owner (it hides owner), so the fuzzer
        // can find such an address (the contract owner) and make this assertion fail on the mutant.

        bool ok = c.approvedToLog(logger);
        assertTrue(ok);
    }
}

